INSERT INTO zhishi_notices (id, real, source, publish_date, title, event, audience, deadline, countdown, materials, entry, confidence, priority, points, digest_one, digest_points, raw, url, site, unit, src_generated_at) VALUES ('ahau-018', TRUE, '经济管理学院', '2026-10-16', '经济管理学院召开纪委工作会议本网讯 10月15日上午，经济管理学院纪委工作会议在经管楼304会议室召开。会议由学院党委副', '校内通知', NULL, NULL, NULL, NULL, NULL, 0.5, 'medium', '[{"text": "本网讯 10月15日上午，经济管理学院纪委工作会议在经管楼304会议室召开", "quote": "本网讯 10月15日上午，经济管理学院纪委工作会议在经管楼304会议室召开"}]'::jsonb, '校内通知：经济管理学院召开纪委工作会议本网讯 10月15日上午，经济管理学院纪委工作会议在', '[{"text": "本网讯 10月15日上午，经济管理学院纪委工作会议在经管楼304会议室召开", "quote": "本网讯 10月15日上午，经济管理学院纪委工作会议在经管楼304会议室召开"}]'::jsonb, '本网讯 10月15日上午，经济管理学院纪委工作会议在经管楼304会议室召开。会议由学院党委副书记、纪委书记周涛主持，院纪委全体委员参加会议。 会议开展集中学习。周涛同志领学习习近平总书记在全国卫生与健康大会上的重要讲话，以及安徽省纪委监委通报的五年来全省全面从严治党、党风廉政建设和反腐败斗争情况；梅莹同志领学中央纪委国家监委、安徽省纪委监委公开通报的六起违反中央八项规定精神典型问题；沈洁同志领学《中国共产党纪律处分条例》第一编总则。 会议围绕学院 2026年度重点工作落实推进、学院党委巡察整改工作落实推进等情况开展', 'https://jgxy.ahau.edu.cn/info/1101/25926.htm', '经济管理学院 · 工作动态', 'jgxy', '2026-11-04 13:33:17') ON CONFLICT (id) DO UPDATE SET source=EXCLUDED.source, publish_date=EXCLUDED.publish_date, title=EXCLUDED.title, event=EXCLUDED.event, deadline=EXCLUDED.deadline, points=EXCLUDED.points, digest_one=EXCLUDED.digest_one, digest_points=EXCLUDED.digest_points, raw=EXCLUDED.raw, url=EXCLUDED.url, site=EXCLUDED.site, unit=EXCLUDED.unit, src_generated_at=EXCLUDED.src_generated_at